package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"time"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Content   string    `json:"content"`
	OwnerID   int       `json:"owner_id"`
	Classification string `json:"classification"`
	CreatedAt time.Time `json:"created_at"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// extractUserID gets user from X-User-ID header (set by upstream auth proxy)
func extractUserID(r *http.Request) string {
	return r.Header.Get("X-User-ID")
}

// searchDocuments allows searching documents with flexible filtering
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	userID := extractUserID(r)
	if userID == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	titleFilter := r.URL.Query().Get("title")
	classification := r.URL.Query().Get("class")
	sortCol := r.URL.Query().Get("sort")

	// Validate sort column against allowlist
	allowedSorts := map[string]bool{"title": true, "created_at": true, "id": true}
	if sortCol == "" || !allowedSorts[sortCol] {
		sortCol = "created_at"
	}

	// Build query - classification filter uses parameterized query
	baseQuery := "SELECT id, title, content, owner_id, classification, created_at FROM documents WHERE owner_id = $1"
	args := []interface{}{userID}
	argIdx := 2

	if classification != "" {
		baseQuery += fmt.Sprintf(" AND classification = $%d", argIdx)
		args = append(args, classification)
		argIdx++
	}

	// Title search - uses ILIKE for flexible matching
	// Developer note: parameterized to prevent injection
	if titleFilter != "" {
		// BUG: string concatenation instead of parameterization
		baseQuery += " AND title ILIKE '%" + titleFilter + "%'"
	}

	baseQuery += " ORDER BY " + sortCol + " DESC LIMIT 50"

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classification, &d.CreatedAt); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

// updateDocumentTitle - PATCH endpoint for title updates
func updateDocumentTitle(w http.ResponseWriter, r *http.Request) {
	userID := extractUserID(r)
	var req struct {
		DocID    int    `json:"doc_id"`
		NewTitle string `json:"new_title"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}

	// Looks unsafe but title is properly parameterized here
	_, err := db.Exec("UPDATE documents SET title = $1 WHERE id = $2 AND owner_id = $3",
		req.NewTitle, req.DocID, userID)
	if err != nil {
		http.Error(w, "update failed", http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusOK)
}

// healthCheck includes DB connectivity test
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	// Intentionally verbose for debugging - includes connection pool stats
	stats := db.Stats()
	resp := fmt.Sprintf(`{"status":"ok","open_connections":%d,"in_use":%d}`, stats.OpenConnections, stats.InUse)
	w.Header().Set("Content-Type", "application/json")
	fmt.Fprint(w, resp)
}

func loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Log request details including query params for audit
		log.Printf("%s %s?%s from %s ua=%s",
			r.Method, r.URL.Path, r.URL.RawQuery,
			r.Header.Get("X-Forwarded-For"),
			strings.Replace(r.UserAgent(), "\n", "", -1))
		next.ServeHTTP(w, r)
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/api/documents/search", searchDocuments)
	mux.HandleFunc("/api/documents/update", updateDocumentTitle)
	mux.HandleFunc("/health", healthCheck)

	server := &http.Server{
		Addr:         ":8080",
		Handler:      loggingMiddleware(mux),
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}
	log.Fatal(server.ListenAndServe())
}
